// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(uint256 amount, address caller) public {
        vm.assume(amount > 0);
        vm.assume(caller != address(0));
        vm.assume(caller != address(c));
        vm.deal(caller, amount);
        vm.prank(caller);
        c.addToBalance{value: amount}();
        uint256 preBalance = c.getBalance(caller);
        vm.prank(caller);
        (bool ok,) = address(c).call(abi.encodeWithSignature("withdrawBalance()"));
        assertTrue(ok);
        uint256 postBalance = c.getBalance(caller);
        assertTrue(postBalance == preBalance - amount);
    }
}
